export type TutorialRole = 'ADMIN' | 'LAWYER' | 'OPERATOR' | 'VIEWER';
export const TUTORIAL_CATALOG_VERSION = 1;
export type TutorialAction = 'inspect' | 'open' | 'fill' | 'confirm' | 'filter' | 'select' | 'download';

export interface TutorialField {
  id: string;
  label: string;
  value: string;
  type?: 'text' | 'select' | 'textarea' | 'date';
  options?: string[];
}

export interface TutorialStep {
  id: string;
  chapterId: string;
  title: string;
  explanation: string;
  instruction: string;
  result: string;
  target: string;
  action: TutorialAction;
  buttonLabel: string;
  fields?: TutorialField[];
  preview?: Array<{ label: string; value: string }>;
  durationSeconds: number;
  route: string;
  roles?: TutorialRole[];
}

export interface TutorialChapter {
  id: string;
  title: string;
  description: string;
  icon: string;
  roles?: TutorialRole[];
  steps: TutorialStep[];
}

const writers: TutorialRole[] = ['ADMIN', 'LAWYER', 'OPERATOR'];
const lawyers: TutorialRole[] = ['ADMIN', 'LAWYER'];
const admins: TutorialRole[] = ['ADMIN'];
type StepInput = Omit<TutorialStep, 'chapterId' | 'target' | 'route' | 'durationSeconds'> & { durationSeconds?: number };

function chapter(id: string, title: string, description: string, icon: string, route: string, steps: StepInput[], roles?: TutorialRole[]): TutorialChapter {
  return {
    id, title, description, icon, ...(roles ? { roles } : {}),
    steps: steps.map((step) => ({
      ...step, id: `${id}-${step.id}`, chapterId: id, target: `tutorial-${id}-${step.id}`, route,
      durationSeconds: step.durationSeconds ?? Math.min(20, Math.max(10, Math.ceil(step.explanation.split(/\s+/).length / 2.5))),
    })),
  };
}

