export const tutorialSteps: TutorialStep[] = tutorialChapters.flatMap((entry) => entry.steps);

export function isTutorialRole(value: unknown): value is TutorialRole {
  return typeof value === 'string' && ['ADMIN', 'LAWYER', 'OPERATOR', 'VIEWER'].includes(value);
}

export function chaptersForRole(role: string | null | undefined): TutorialChapter[] {
  const activeRole = isTutorialRole(role) ? role : 'VIEWER';
  return tutorialChapters
    .filter((entry) => !entry.roles || entry.roles.includes(activeRole))
    .map((entry) => ({ ...entry, steps: entry.steps.filter((step) => !step.roles || step.roles.includes(activeRole)) }))
    .filter((entry) => entry.steps.length > 0);
}

export function stepsForRole(role: string | null | undefined): TutorialStep[] {
  return chaptersForRole(role).flatMap((entry) => entry.steps);
}
